TLM.f("Sancti/08-01r",{"officium":"Ss. Martyrum Machabæorum","rule":["vide C3;"],"fallback":"Commune/C3","from":{"Tractus":"Commune/C3"},"sections":{"Introitus":[{"k":"ref","la":"Ps 33:18"},{"k":"text","la":"Clamavérunt justi, et Dóminus exaudívit eos; et ex ómnibus tribulatiónibus eórum liberávit eos."},{"k":"ref","la":"Ps 33:2"},{"k":"text","la":"Benedícam Dóminum in omni témpore; semper laus ejus in ore meo."},{"k":"macro","name":"Glória"},{"k":"text","la":"Clamavérunt justi, et Dóminus exaudívit eos; et ex ómnibus tribulatiónibus eórum liberávit eos."}],"Oratio":[{"k":"text","la":"Fratérna nos, Dómine, Mártyrum tuórum coróna lætíficet: quæ et fídei nostræ præbeat increménta virtútum; et multíplici nos suffrágio consolétur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Lectio Epistolæ Sancti Pauli Apostoli ad Hebrǽos"},{"k":"ref","la":"Heb 11:33-39"},{"k":"text","la":"Fratres: sancti per fidem vicérunt regna, operáti sunt justítiam, adépti sunt repromissiónes, obturavérunt ora leónum, extinxérunt ímpetum ignis, effugérunt áciem gládii, convaluérunt de infirmitáte, fortes facti sunt in bello, castra vertérunt exterórum: accepérunt mulíeres de resurrectióne mórtuos suos: álii autem disténti sunt non suscipiéntes redemptiónem ut meliórem invenírent resurrectiónem. Alii vero ludíbria, et vérbera expérti, ínsuper et víncula, et cárceres: lapidáti sunt, secti sunt, tentáti sunt, in occisióne gládii mórtui sunt, circuiérunt in melótis, in péllibus caprínis, egéntes, angustiáti, afflícti: quibus dignus non erat mundus: in solitudínibus errántes, in móntibus, in spelúncis, et in cavérnis terræ. Et hi omnes testimónio fídei probáti, invénti sunt in Christo Iesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 132:1-2"},{"k":"text","la":"Ecce, quam bonum et quam jucúndum, habitáre fratres in unum!"},{"k":"text","la":"Sicut unguéntum in cápite, quod descéndit in barbam, barbam Aaron. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Hæc est vera fratérnitas, quæ vicit mundi crímina: Christum secúta est, ínclita tenens regna cœléstia. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Exod 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 12:1-8"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Atténdite a ferménto pharisæórum, quod est hypócrisis. Nihil autem opértum est, quod non revelétur: neque abscónditum, quod non sciátur. Quóniam, quæ in ténebris dixístis, in lúmine dicéntur: et quod in aurem locúti estis in cubículis, prædicábitur in tectis. Dico autem vobis amícis meis: Ne terreámini ab his, qui occídunt corpus, et post hæc non habent ámplius quid fáciant. Osténdam autem vobis, quem timeátis: timéte eum, qui postquam occíderit, habet potestátem míttere in gehénnam. Ita dico vobis: hunc timéte. Nonne quinque pásseres véneunt dipóndio, et unus ex illis non est in oblivióne coram Deo? Sed et capílli cápitis vestri omnes numeráti sunt. Nolíte ergo timére: multis passéribus pluris estis vos. Dico autem vobis: Omnis, quicúmque conféssus fúerit me coram homínibus, et Fílius hóminis confitébitur illum coram Angelis Dei."}],"Offertorium":[{"k":"ref","la":"Ps 149:5-6"},{"k":"text","la":"Exsultábunt sancti in glória; lætabúntur in cubílibus suis. Exaltatiónes Dei in gútture eórum. Allelúia."}],"Secreta":[{"k":"text","la":"Mystéria tua, Dómine, pro sanctórum Mártyrum tuórum honóre, devóta mente tractémus: quibus et præsídium nobis crescat et gáudium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 12:4"},{"k":"text","la":"Dico autem vobis amícis meis: Ne terreámini ab his qui occídunt corpus."}],"Postcommunio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut, quorum memóriam sacraménti participatióne recólimus, fidem quoque proficiéndo sectémur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"a0770628901df95e":{"t":"<i>Pomolimo se</i>.\nNeka nas, Gospodine, razveseljuje bratski vijenac tvojih mučenika, koji neka nam dade porast kreposti i utješi nas mnogostrukom pomoći.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"25ac1c91101fe367":{"t":"Daj, Gospodine, da tvoje tajne na čast tvojih svetih obavljamo pobožnom dušom pa da nam po njima poraste i zaštita i radost.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"b766bab64809379b":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, da napredovanjem nasljedujemo vjeru onih kojih spomen slavimo sudjelovanjem u ovom otajstvu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
